package dev.joaomendonca.agendapro.appointment.infrastructure;import dev.joaomendonca.agendapro.appointment.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.time.LocalDateTime;import java.util.*;
public interface AppointmentRepository extends JpaRepository<Appointment,UUID>{List<Appointment> findAllByTenantIdAndStartsAtBetweenOrderByStartsAt(UUID tenantId,LocalDateTime from,LocalDateTime to);Optional<Appointment> findByIdAndTenantId(UUID id,UUID tenantId);
 @Query("select count(a)>0 from Appointment a where a.tenantId=:tenantId and a.employeeId=:employeeId and a.status <> dev.joaomendonca.agendapro.appointment.domain.AppointmentStatus.CANCELLED and a.id<>:ignoredId and a.startsAt<:endsAt and a.endsAt>:startsAt") boolean hasConflict(@Param("tenantId") UUID tenantId,@Param("employeeId") UUID employeeId,@Param("startsAt") LocalDateTime startsAt,@Param("endsAt") LocalDateTime endsAt,@Param("ignoredId") UUID ignoredId);}
